class Widget
{
    public Widget() => Render();          // виртуальный вызов
    protected virtual void Render() { }
}

class Label : Widget
{
    string font = "Arial";                // заполнено до base()
    string text;
    public Label() { text = "Привет"; }   // ещё не выполнялось
    protected override void Render() =>
        Console.WriteLine($"{font}: {text.Length}");
}

